#!/usr/bin/env bash
# push_onix_citadel.sh — publish the Onix Citadel pack to the citadel branch
# of github.com/RohanDaCoder/OnixMinigames.
#
# The deploy key is regenerated by gen_deploy_key.py onix_repo and mirrored
# into the citadel-docs repo's .git/config (sync.onixrepokey) so container
# recycles cannot lose it. Register the public half on GitHub with write
# access (Settings -> Deploy keys -> onix_repo-sync) once; this script does
# the rest. Safe to re-run: it fast-forwards or recreates the branch.

set -euo pipefail

ROOT=/home/z/my-project
KEY=$ROOT/.secrets/onix_repo_ed25519
PUB="${KEY}.pub"
MIRROR_B64=$(git -C "$ROOT" config --get sync.onixrepokey || true)
CLONE=${CLONE:-$ROOT/onixminigames}
BRANCH=citadel

[[ "${MIRROR_B64}" == base64:* ]] || {
    echo "push: no key mirror in .git/config — run: python3 scripts/gen_deploy_key.py onix_repo"
    exit 1
}

# .secrets/ is wiped by container recycles; the mirror always restores it.
if [[ ! -f "$KEY" ]]; then
    base64 -d <<<"${MIRROR_B64#base64:}" > "$KEY"
    chmod 600 "$KEY"
    git -C "$ROOT" config --get sync.onixrepokeypub > "$PUB"
    echo "push: key restored from mirror into $KEY"
fi

export GIT_SSH_COMMAND="python3 $ROOT/scripts/git_ssh.py -i $KEY -o IdentitiesOnly=yes"

if [[ ! -d "$CLONE/.git" ]]; then
    rm -rf "$CLONE"
    git clone git@github.com:RohanDaCoder/OnixMinigames.git "$CLONE"
fi

git -C "$CLONE" fetch origin
git -C "$CLONE" remote prune origin >/dev/null

# Base the branch on the repo's default head; replace our directory
# wholesale so deletions propagate too.
git -C "$CLONE" switch -q "$BRANCH" 2>/dev/null ||
    git -C "$CLONE" switch -q -c "$BRANCH" origin/HEAD
git -C "$CLONE" reset -q --hard origin/HEAD

mkdir -p "$CLONE/packs/onixmg/games" "$CLONE/packs/onixmg/builds"
rm -rf "$CLONE/packs/onixmg"
mkdir -p "$CLONE/packs/onixmg"
cp -r "$ROOT/scripts/onixmg_citadel/pack/." "$CLONE/packs/onixmg/"
cp "$ROOT/scripts/onixmg_citadel/README.md" "$CLONE/packs/onixmg/README.md"

git -C "$CLONE" add -A packs/onixmg
if git -C "$CLONE" diff --cached --quiet; then
    echo "push: nothing to do — branch already up to date"
    exit 0
fi

git -C "$CLONE" -c user.name="onix-sync" -c user.email="onix-sync@container" \
    commit -q -m "citadel: 1:1 port of the live Skript server (maps, messages, games)

Pack source: scripts/onixmg_citadel/pack in citadel-docs. The live
Paper server (onixminigames.minefort.com) was the source of truth:
its nine Skript files, its FAWE schematics, its LuckPerms/TAB/LPC/
Essentials config and its server.properties MOTD."

git -C "$CLONE" push -u origin "$BRANCH"
echo "push: $BRANCH updated on github.com/RohanDaCoder/OnixMinigames"
